package com.wireturn.app.domain

import org.junit.Assert.*
import org.junit.Test

class TunaRoutingDesktopContractTest {
    @Test fun readsPythonEditorMixedRuleFixture() {
        val command = TunaRoutingLink.parse("tuna://routing/v1?")
        assertEquals("TCP", command.policy.remote.transport)
        assertEquals("UDP", command.policy.domestic.transport)
        assertEquals(4, command.policy.routing.rules.size)
        assertEquals(2, command.apps!!.packages.size)
        assertFalse(command.apps!!.bypass)
        assertFalse(command.policy.hosts.isEmpty())
    }
    @Test fun readsActualPythonBuilderExport() {
        // Generated by policy.tuna_link(policy.document(policy.defaults(), ["com.android.chrome"]))
        val command = TunaRoutingLink.parse("tuna://routing/v1?")
        assertEquals("Мой маршрут", command.policy.name)
        assertEquals("DOH", command.policy.remote.transport)
        assertEquals("UDP", command.policy.domestic.transport)
        assertEquals(setOf("com.android.chrome"), command.apps!!.packages)
        assertTrue(command.apps!!.bypass)
        assertFalse(command.policy.fakeDns)
        assertTrue(command.policy.warnings.isEmpty())
    }
}
